import React, { useEffect, useState } from 'react';
import '../styles/home.css';
import { FaHome, FaPaperPlane, FaCompass, FaHeart, FaPlusSquare } from 'react-icons/fa';

const Home = () => {
  const [posts, setPosts] = useState([]);
  const [suggestions, setSuggestions] = useState([]);

  useEffect(() => {
    setPosts([
      {
        id: 1,
        user: 'Aman',
        content: 'Just got placed at Amazon!',
        image: 'https://source.unsplash.com/400x300/?amazon,office',
        likes: 10,
        comments: 2,
        time: '2h ago',
      },
      {
        id: 2,
        user: 'Simran',
        content: 'Join my DSA bootcamp!',
        image: 'https://source.unsplash.com/400x300/?code,bootcamp',
        likes: 5,
        comments: 1,
        time: '5h ago',
      },
    ]);

    setSuggestions([
      { id: 1, name: 'Harpreet Singh', avatar: 'https://i.pravatar.cc/40?img=1' },
      { id: 2, name: 'Mandeep Kaur', avatar: 'https://i.pravatar.cc/40?img=2' },
    ]);
  }, []);

  return (
    <div className="home-wrapper">
      {/* Header */}
      <header className="header">
        <div className="logo">CAMPUS NETWORK</div>
        <nav className="nav-icons">
          <FaHome />
          <FaPaperPlane />
          <FaPlusSquare />
          <FaCompass />
          <FaHeart />
        </nav>
        <img className="profile-pic" src="https://i.pravatar.cc/30" alt="profile" />
      </header>

      <div className="home-container">
        {/* Left Sidebar */}
        <div className="left-sidebar">
          <div className="stories">
            <h4>Stories</h4>
            <div className="stories-scroll">
              {[...Array(8)].map((_, i) => (
                <div className="story" key={i}>
                  <img src={`https://i.pravatar.cc/40?img=${i + 3}`} alt="story" />
                  <span>User{i + 1}</span>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Main Feed */}
        <div className="main-feed">
          {posts.map(post => (
            <div className="post-card" key={post.id}>
              <div className="post-header">
                <img src={`https://i.pravatar.cc/30?u=${post.user}`} alt="avatar" />
                <span>{post.user}</span>
              </div>
              <img src={post.image} alt="post" className="post-image" />
              <div className="post-content">
                <p>{post.content}</p>
                <div className="post-meta">
                  ❤️ {post.likes} · 💬 {post.comments} · ⏰ {post.time}
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* Right Sidebar */}
        <div className="right-sidebar">
          <div className="profile-summary">
            <img src="https://i.pravatar.cc/40?img=10" alt="me" />
            <div>
              <strong>you_user</strong>
              <small>Your Name</small>
            </div>
          </div>
          <h4>Suggestions</h4>
          {suggestions.map(s => (
            <div className="suggestion" key={s.id}>
              <img src={s.avatar} alt="sugg" />
              <span>{s.name}</span>
              <button>Follow</button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Home;
